<script setup>
import {ref,watch,computed} from 'vue';import {Save,Plus,ArrowUp,ArrowDown,Trash2,Image,Upload} from '@lucide/vue';
const props=defineProps({site:Object,busy:Boolean,editable:Boolean,assets:Array,imageSource:Function});const emit=defineEmits(['save','upload','dirty','review']);
const draft=ref(JSON.parse(JSON.stringify(props.site))),tab=ref('home'),changed=ref(false),file=ref(null);
watch(()=>props.site,value=>{draft.value=JSON.parse(JSON.stringify(value));changed.value=false;emit('dirty',false);});
function edit(){changed.value=true;emit('dirty',true);}
function move(index,step){const a=draft.value.navigation;[a[index],a[index+step]]=[a[index+step],a[index]];edit();}
const fields=[['title','Überschrift, erste Zeile'],['emphasis','Überschrift, zweite Zeile'],['intro','Einleitung'],['actionText','Beschriftung des Suchlinks'],['topicsTitle','Überschrift der Themen'],['searchPlaceholder','Hinweis im Suchfeld'],['workNote','Hinweis zum Bearbeitungsstand'],['featureTitle','Titel des hervorgehobenen Beitrags'],['featureText','Kurzbeschreibung'],['featureLabel','Beschriftung des Links'],['featureLink','Linkziel'],['featureNote','Zusätzlicher Hinweis'],['bottomTitle','Überschrift des unteren Abschnitts'],['bottomText','Text des unteren Abschnitts']];
const imageOptions=computed(()=>[...new Set(['/images/voidborn-rift.png',draft.value.home.image,...(props.assets||[]).map(a=>'/'+a.path.slice('docs/public/'.length))])]);
</script>
<template>
 <div class="page-heading"><div><h1>Website bearbeiten</h1><p>Texte, Bilder und Links. Das rote Theme bleibt erhalten.</p></div><div class="inline-actions"><button class="secondary" :disabled="busy||changed" @click="emit('review')">Vorschau & Veröffentlichung</button><button class="primary" :disabled="busy||!changed||!editable" @click="emit('save',draft)"><Save :size="17"/> Entwurf speichern</button></div></div>
 <div class="status-tabs" role="tablist" aria-label="Website-Einstellungen"><button v-for="t in [{id:'home',label:'Startseite'},{id:'navigation',label:'Navigation'},{id:'footer',label:'Footer'}]" role="tab" :aria-selected="tab===t.id" @click="tab=t.id">{{t.label}}</button></div>
 <p class="muted">{{changed?'Ungespeicherte Änderungen':'Gespeicherter Entwurf'}} · Erst eine eigene Veröffentlichung übernimmt die Einstellungen auf die Website.</p>
 <fieldset :disabled="!editable||busy" class="site-settings" @input="edit" @change="edit">
  <template v-if="tab==='home'"><div class="site-image"><img :src="imageSource(draft.home.image)" :alt="draft.home.imageAlt"><div><h2>Startseitenbild</h2><label>Bild aus der Mediensammlung<select v-model="draft.home.image"><option v-for="path in imageOptions" :value="path">{{path.split('/').pop()}}</option></select></label><label>Bildbeschreibung<input v-model="draft.home.imageAlt"><small>Bei rein dekorativen Bildern leer lassen.</small></label><label>Neues Bild<input type="file" accept="image/png,image/jpeg,image/webp" @input.stop @change.stop="file=$event.target.files[0]"><small>PNG, JPEG oder WebP · maximal 2 MiB. Ungespeicherte Texte zuerst speichern.</small></label><button class="secondary" :disabled="!file||changed" @click="emit('upload',{file,alt:draft.home.imageAlt})"><Upload :size="16"/> Bild als Entwurf übernehmen</button></div></div><div class="settings-fields"><label v-for="[key,label] in fields">{{label}}<textarea v-if="['intro','workNote','bottomText','featureText'].includes(key)" v-model="draft.home[key]" rows="3"></textarea><input v-else v-model="draft.home[key]" :maxlength="2000"></label></div><h2>Links im unteren Abschnitt</h2><div v-for="(link,index) in draft.home.bottomLinks" class="nav-edit-row"><label>Beschriftung<input v-model="link.text"></label><label>Ziel<input v-model="link.link"></label><button :aria-label="link.text+' entfernen'" @click="draft.home.bottomLinks.splice(index,1);edit()"><Trash2 :size="17"/></button></div><button :disabled="draft.home.bottomLinks.length>=4" class="secondary" @click="draft.home.bottomLinks.push({text:'Neuer Link',link:'/guides/'});edit()"><Plus :size="16"/> Link hinzufügen</button></template>
  <template v-if="tab==='navigation'"><label>Name in der Kopfleiste<input v-model="draft.brand" maxlength="60"></label><h2>Links in der oberen Leiste</h2><p class="muted">Interne Ziele beginnen mit /, externe mit https://. Die Reihenfolge entspricht der Website.</p><div v-for="(link,index) in draft.navigation" class="nav-edit-row"><label>Beschriftung<input v-model="link.text" maxlength="100"></label><label>Zieladresse<input v-model="link.link" maxlength="2000"></label><div class="inline-actions"><button :disabled="index===0" :aria-label="link.text+' nach oben'" @click="move(index,-1)"><ArrowUp :size="17"/></button><button :disabled="index===draft.navigation.length-1" :aria-label="link.text+' nach unten'" @click="move(index,1)"><ArrowDown :size="17"/></button><button :disabled="draft.navigation.length<=1" :aria-label="link.text+' entfernen'" @click="draft.navigation.splice(index,1);edit()"><Trash2 :size="17"/></button></div></div><button class="secondary" :disabled="draft.navigation.length>=8" @click="draft.navigation.push({text:'Neuer Link',link:'/guides/'});edit()"><Plus :size="17"/> Link hinzufügen</button></template>
  <template v-if="tab==='footer'"><label>Hinweis<textarea v-model="draft.footer.message"></textarea></label><label>Rechtehinweis<textarea v-model="draft.footer.copyright"></textarea></label></template>
 </fieldset>
</template>
